head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var temp = WebSquare.xml.parse("<testNode><testValue>aaaa</testValue></testNode>");
    WebSquare.ModelUtil.setInstanceNode(temp, "response", null, "append");
};
scwin.checkVal = function() {
    //[] 인데 []게 '' 의미? 그래서 에러나는 엔진과 반대로
    return WebSquare.DataCollection.comp.dataMap1.getArray()[0] != [];
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'treeView1_col_icon_navi_1').getElementsByClassName('w2treeview_icon_navi')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'treeView1_child_1').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
